import { describe, it, expect } from 'vitest';
import crypto from 'node:crypto';
import {
  parseOpenSshCertificate,
  validateOpenSshCertificate,
  computeOpenSshFingerprint,
  isoToEpochSeconds,
} from '../../src/main/ca/sshCertificateUtils';
import { exportSshWirePublicKey } from '../../src/main/ca/sshPublicKeyFormat';
import { buildUserCertificate } from '../helpers/sshTestCert';

describe('sshCertificateUtils', () => {
  // A real RSA user certificate generated by Step-CA in our test environment
  const sampleRsaCert =
    ''; // pragma: allowlist secret -- public SSH user certificate used as a test fixture

  it('parses an OpenSSH user certificate correctly', () => {
    const info = parseOpenSshCertificate(sampleRsaCert);
    expect(info.certType).toBe('user');
    expect(info.keyId).toBe('alun@alun.se');
    expect(info.principals).toEqual(['alun', 'alun@alun.se']);
    expect(info.serial).toBe('97609306611426011');
    expect(info.signatureKeyFingerprint).toBe('SHA256:3Qwy3Co+0wbKmUHbe/HS86EFTVt4TqVPCzSbezElmtQ');
    expect(info.publicKeyFingerprint).toBe('SHA256:tlWi0NWrBy4gD9QJC400gu6K2FuNAqEkdbFMXrQwEpg');
    expect(info.validAfter).toBe('2026-10-31T15:15:26.000Z');
    expect(info.validBefore).toBe('2026-11-01T07:16:26.000Z');
  });

  it('parses certificate with prefix type and comment', () => {
    const fullLine = `ssh-rsa-cert-v01@openssh.com ${sampleRsaCert} my-key-comment`;
    const info = parseOpenSshCertificate(fullLine);
    expect(info.certType).toBe('user');
    expect(info.keyId).toBe('alun@alun.se');
  });

  it('rejects malformed certificates', () => {
    expect(() => parseOpenSshCertificate('not-base64-at-all!!')).toThrow();
    expect(() => parseOpenSshCertificate(Buffer.from('too-short'))).toThrow(/too short/);
  });

  it('rejects unsupported certificate key types', () => {
    const keyType = Buffer.from('sk-ssh-ed25519-cert-v01@openssh.com');
    const nonce = Buffer.alloc(32, 1);
    const len1 = Buffer.alloc(4);
    len1.writeUInt32BE(keyType.length, 0);
    const len2 = Buffer.alloc(4);
    len2.writeUInt32BE(nonce.length, 0);
    const certBlob = Buffer.concat([len1, keyType, len2, nonce, Buffer.alloc(100)]);
    expect(() => parseOpenSshCertificate(certBlob)).toThrow(/Unsupported certificate key type/);
  });

  describe('validateOpenSshCertificate', () => {
    const now = new Date('2026-10-31T16:00:00.000Z').getTime();

    it('validates a valid user certificate', () => {
      const info = parseOpenSshCertificate(sampleRsaCert);
      const res = validateOpenSshCertificate(info, { now });
      expect(res.valid).toBe(true);
      expect(res.error).toBeUndefined();
    });

    it('rejects an expired certificate', () => {
      const info = parseOpenSshCertificate(sampleRsaCert);
      const futureTime = new Date('2026-11-02T12:00:00.000Z').getTime();
      const res = validateOpenSshCertificate(info, { now: futureTime });
      expect(res.valid).toBe(false);
      expect(res.error).toMatch(/expired/);
    });

    it('rejects a host certificate when user certificate is expected', () => {
      const info = { ...parseOpenSshCertificate(sampleRsaCert), certType: 'host' as const };
      const res = validateOpenSshCertificate(info, { now });
      expect(res.valid).toBe(false);
      expect(res.error).toMatch(/expected a user certificate/);
    });

    it('rejects when principals are empty', () => {
      const info = { ...parseOpenSshCertificate(sampleRsaCert), principals: [] };
      const res = validateOpenSshCertificate(info, { now });
      expect(res.valid).toBe(false);
      expect(res.error).toMatch(/no principals/);
    });

    it('verifies public key fingerprint match', () => {
      const info = parseOpenSshCertificate(sampleRsaCert);
      const resOk = validateOpenSshCertificate(info, {
        now,
        expectedPublicKeyFingerprint: info.publicKeyFingerprint,
      });
      expect(resOk.valid).toBe(true);

      const resBad = validateOpenSshCertificate(info, {
        now,
        expectedPublicKeyFingerprint: 'SHA256:differentFingerprint123',
      });
      expect(resBad.valid).toBe(false);
      expect(resBad.error).toMatch(/public key mismatch/);
    });

    it('verifies CA signature key fingerprint match', () => {
      const info = parseOpenSshCertificate(sampleRsaCert);
      const resOk = validateOpenSshCertificate(info, {
        now,
        expectedCaFingerprint: 'SHA256:3Qwy3Co+0wbKmUHbe/HS86EFTVt4TqVPCzSbezElmtQ',
      });
      expect(resOk.valid).toBe(true);

      const resBad = validateOpenSshCertificate(info, {
        now,
        expectedCaFingerprint: 'SHA256:wrongCaFingerprint',
      });
      expect(resBad.valid).toBe(false);
      expect(resBad.error).toMatch(/CA mismatch/);
    });
  });

  describe('computeOpenSshFingerprint', () => {
    it('computes standard SHA256 base64 fingerprint without trailing padding', () => {
      const buf = Buffer.from('test-wire-bytes');
      const fp = computeOpenSshFingerprint(buf);
      expect(fp).toMatch(/^SHA256:[A-Za-z0-9+/]+$/);
      expect(fp.endsWith('=')).toBe(false);
    });
  });

  describe('isoToEpochSeconds', () => {
    it('floors an ISO timestamp to whole epoch seconds', () => {
      expect(isoToEpochSeconds('2026-11-01T00:00:00.999Z')).toBe(Date.UTC(2026, 10, 1) / 1000);
    });
  });

  describe('validity window and lifetime (certificates built for a fixed "now")', () => {
    const NOW_SEC = 1_800_000_000;
    const NOW_MS = NOW_SEC * 1000;
    const subject = () => exportSshWirePublicKey(crypto.generateKeyPairSync('ed25519').publicKey).wireBase64;
    /** A certificate that is valid from certNowSec - 60 s until certNowSec + validForSeconds. */
    const certAt = (certNowSec: number, validForSeconds = 3600) =>
      parseOpenSshCertificate(buildUserCertificate({ subjectWireBase64: subject(), nowSec: certNowSec, validForSeconds }).wire);

    it('rejects a certificate that is not valid yet and says so', () => {
      const result = validateOpenSshCertificate(certAt(NOW_SEC + 3600), { now: NOW_MS });
      expect(result.valid).toBe(false);
      expect(result.error).toMatch(/not yet valid/);
    });

    it('allows exactly five minutes of clock skew before the start of the validity window, and not a second more', () => {
      // validAfter is certNowSec - 60 s, so these start 300 s and 301 s after "now".
      expect(validateOpenSshCertificate(certAt(NOW_SEC + 360), { now: NOW_MS })).toEqual({ valid: true });
      const late = validateOpenSshCertificate(certAt(NOW_SEC + 361), { now: NOW_MS });
      expect(late.valid).toBe(false);
      expect(late.error).toMatch(/not yet valid/);
    });

    it('rejects a certificate whose lifetime exceeds maxTtlSeconds (plus a minute of slack)', () => {
      // validAfter = now - 60 s, validBefore = now + 7200 s: 7260 s in total.
      const cert = certAt(NOW_SEC, 7200);
      const tooLong = validateOpenSshCertificate(cert, { now: NOW_MS, maxTtlSeconds: 3600 });
      expect(tooLong.valid).toBe(false);
      expect(tooLong.error).toMatch(/exceeds maximum allowed TTL/);
    });

    it('accepts a lifetime of exactly maxTtlSeconds + 60 s, and any lifetime when no maximum is given', () => {
      const cert = certAt(NOW_SEC, 7200);
      expect(validateOpenSshCertificate(cert, { now: NOW_MS, maxTtlSeconds: 7200 })).toEqual({ valid: true });
      expect(validateOpenSshCertificate(cert, { now: NOW_MS })).toEqual({ valid: true });
    });
  });

  describe('parseOpenSshCertificate input handling', () => {
    const wire = () => buildUserCertificate({ subjectWireBase64: exportSshWirePublicKey(crypto.generateKeyPairSync('ed25519').publicKey).wireBase64 });

    it('rejects a certificate whose nonce is not 32 bytes, naming the length', () => {
      const str = (b: Buffer) => Buffer.concat([Buffer.from([0, 0, 0, b.length]), b]);
      const blob = Buffer.concat([
        str(Buffer.from('ssh-ed25519-cert-v01@openssh.com')),
        str(Buffer.alloc(16, 7)), // a 16 byte nonce
        Buffer.alloc(32, 0),
      ]);
      expect(() => parseOpenSshCertificate(blob)).toThrow('Invalid certificate nonce length: expected 32 bytes, got 16');
    });

    it('reports a line that has the certificate type but no certificate data as too short, not as a crash', () => {
      expect(() => parseOpenSshCertificate('ssh-ed25519-cert-v01@openssh.com')).toThrow(/buffer is too short/);
    });

    it('reads the same certificate from raw bytes, a bare base64 blob and a full authorized_keys-style line', () => {
      const cert = wire();
      const fromBytes = parseOpenSshCertificate(cert.wire);
      expect(parseOpenSshCertificate(cert.wireBase64)).toEqual(fromBytes);
      expect(parseOpenSshCertificate(cert.line)).toEqual(fromBytes);
    });
  });
});
